#include "ThreatRuntime.hpp"
#include <cmath>
namespace elysium::fortress {static std::uint64_t mix(std::uint64_t x){x^=x>>30;x*=0xbf58476d1ce4e5b9ULL;x^=x>>27;x*=0x94d049bb133111ebULL;x^=x>>31;return x?x:1;}bool ThreatRuntime::addFamily(ThreatFamily f,std::string&w){if(!f.id||f.causeTags.empty()||f.downstreamPipelines.empty()){w="threat requires cause and pipeline";return false;}return families_.emplace(f.id,std::move(f)).second;}std::optional<SiegePlan>ThreatRuntime::plan(ContentId id,std::uint64_t seed,const std::vector<DefenseNode>&k,std::string&w)const{if(!families_.count(id)){w="unknown threat";return std::nullopt;}if(k.empty()){w="no known defense nodes";return std::nullopt;}auto v=k;std::sort(v.begin(),v.end(),[](auto&a,auto&b){double sa=a.value*a.knownConfidence-a.exposure;double sb=b.value*b.knownConfidence-b.exposure;return sa==sb?a.id<b.id:sa>sb;});SiegePlan p{mix(seed^id),id,{},{},0};for(std::size_t i=0;i<std::min<std::size_t>(4,v.size());++i){p.targets.push_back(v[i].id);p.score+=v[i].value*v[i].knownConfidence;}return p;}}
